// Spell masks for the declarative talent mods below. One bit per
// ability, so a talent that reads "your instant cast spells" or "your
// Devouring Plague" is a line of SpellModConfig against a set of bits
// rather than a closure that re-derives the set every time a spell
// registers. Bits are never renumbered: a mask is also how a saved mod
// config and a log line name an ability.
const (
	// Bit 0 is reserved so no mask ever equals the zero value, which
	// AddStaticMod's ClassMask treats as "no filter" rather than "no
	// abilities".
	PriestSpellMaskMindFlay uint64 = 1 << (iota + 1)
	PriestSpellMaskDevouringPlague
	PriestSpellMaskShadowWordPain
	PriestSpellMaskShadowWordDeath
	PriestSpellMaskSmite
	PriestSpellMaskHolyFire
	PriestSpellMaskLesserHeal
	PriestSpellMaskHeal
	PriestSpellMaskFlashHeal
	PriestSpellMaskGreaterHeal
	PriestSpellMaskRenew
	PriestSpellMaskPrayerOfHealing
	PriestSpellMaskPowerWordShield
	PriestSpellMaskPenance
	PriestSpellMaskHolyNova
	PriestSpellMaskPrayerOfMending
	PriestSpellMaskDesperatePrayer
	PriestSpellMaskLightwell
	PriestSpellMaskMindBlast
	PriestSpellMaskVampiricEmbrace
	_ // Binding Heal's bit until client 1.60.1.70755 dropped its trainer rows; never reused
	PriestSpellMaskDivineGrace
	PriestSpellMaskContingencyPlanHeal
	PriestSpellMaskInnerFire
	PriestSpellMaskPowerInfusion
)

// PriestSpellMaskInstantShadowDamage is every Shadow damage spell this
// package registers whose client cast_time_ms is 0 (talents/priest.json
// build 1.60.1.70009's spellconst: Mind Flay, Devouring Plague, Shadow
// Word: Pain and Shadow Word: Death all carry cast_time_ms 0, unlike
// Mind Blast, Smite and Holy Fire).
const PriestSpellMaskInstantShadowDamage = PriestSpellMaskMindFlay | PriestSpellMaskDevouringPlague |
	PriestSpellMaskShadowWordPain | PriestSpellMaskShadowWordDeath

// PriestSpellMaskInstantHealing is every healing spell whose client
// cast_time_ms is 0 and that heals directly or over time: Renew, Penance,
// Holy Nova, Prayer of Mending and Desperate Prayer. Power Word: Shield is
// instant too but absorbs rather than heals, so Twin Disciplines
// ("damage and healing of your instant cast spells") leaves it out.
const PriestSpellMaskInstantHealing = PriestSpellMaskRenew | PriestSpellMaskPenance |
	PriestSpellMaskHolyNova | PriestSpellMaskPrayerOfMending | PriestSpellMaskDesperatePrayer

// PriestSpellMaskTwinDisciplines is what Twin Disciplines raises: the
// instant Shadow damage and instant heals its client masks name (1225132
// eff0 0x19480020/0x18012/0/0x200000, eff1 0xa08060/0/0/0x10). Prayer of
// Mending is named through its heal spells (401863, 1313379, 1313381,
// class mask 0/0/0/0x200000), not its cast or its jump; the engine heals
// through the cast, so the cast carries it.
// The racial heals are named too: Divine Grace (1277370-1277378, mask
// 0x1000000) by eff0, Contingency Plan's heal over time (1277456-1277460,
// mask 0x20) by both effects.
const PriestSpellMaskTwinDisciplines = PriestSpellMaskInstantShadowDamage | PriestSpellMaskInstantHealing |
	PriestSpellMaskDivineGrace | PriestSpellMaskContingencyPlanHeal

// PriestSpellMaskMentalAgility is what Mental Agility's cost modifier
// names: the client mask of 14520 (SpellEffect 687728, aura 108 misc 14),
// not its "instant cast spells" text. It leaves out Mind Flay, Shadow
// Word: Death, Penance and Desperate Prayer, and names Inner Fire (mask
// 0x2 on every rank).
const PriestSpellMaskMentalAgility = PriestSpellMaskSmite | PriestSpellMaskHolyFire |
	PriestSpellMaskShadowWordPain | PriestSpellMaskDevouringPlague | PriestSpellMaskRenew |
	PriestSpellMaskPowerWordShield | PriestSpellMaskHolyNova | PriestSpellMaskPrayerOfMending |
	PriestSpellMaskVampiricEmbrace | PriestSpellMaskInnerFire | PriestSpellMaskPowerInfusion

// PriestSpellMaskSpiritualHealing is what Spiritual Healing (14898) names:
// the direct heals of SpellEffect 692104 (Lesser Heal, Heal, Greater Heal,
// Flash Heal, Prayer of Healing, Holy Nova, Desperate Prayer, Penance,
// and Prayer of Mending) and Renew, the one heal over time of
// 1239404. Lightwell's renew and Holy Binding carry no class options, and
// a shield absorbs rather than heals. Its eff0 also names the racial
// heals: Divine Grace (mask 0x1000000) and Contingency Plan's heal over
// time (mask 0x20).
const PriestSpellMaskSpiritualHealing = PriestSpellMaskLesserHeal | PriestSpellMaskHeal |
	PriestSpellMaskGreaterHeal | PriestSpellMaskFlashHeal | PriestSpellMaskPrayerOfHealing |
	PriestSpellMaskHolyNova | PriestSpellMaskDesperatePrayer | PriestSpellMaskPenance |
	PriestSpellMaskPrayerOfMending | PriestSpellMaskRenew |
	PriestSpellMaskDivineGrace | PriestSpellMaskContingencyPlanHeal

type Priest struct {
	core.Character
	Talents *proto.PriestTalents

	Latency float64

	DarkSacrifice     []*core.Spell
	DesperatePrayer   []*core.Spell
	DevouringPlague   []*core.Spell
	FlashHeal         []*core.Spell
	GreaterHeal       []*core.Spell
	Heal              []*core.Spell
	HolyFire          []*core.Spell
	HolyNova          []*core.Spell
	InnerFire         []*core.Spell
	InnerFocus        *core.Spell
	LesserHeal        []*core.Spell
	Lightwell         []*core.Spell
	LightwellAura     *core.Aura
	lightwell         lightwellState
	MindBlast         []*core.Spell
	MindFlay          [][]*core.Spell // 1 entry for each tick for each rank
	Penance           []*core.Spell
	PowerInfusion     *core.Spell
	PowerWordShield   []*core.Spell
	PrayerOfHealing   []*core.Spell
	PrayerOfMending   []*core.Spell
	Renew             []*core.Spell
	Shadowfiend       *core.Spell
	Shadowform        *core.Spell
	Shoot             *core.Spell
	ShadowWeavingProc *core.Spell
	ShadowWordDeath   []*core.Spell
	ShadowWordPain    []*core.Spell
	Smite             []*core.Spell
	Starshards        [][]*core.Spell
	VampiricEmbrace   *core.Spell

	InnerFocusAura *core.Aura
	ShadowformAura *core.Aura
	SpiritTapAura  *core.Aura

	DarkInspirationAura *core.Aura

	ShadowWeavingAura    *core.Aura
	VampiricEmbraceAuras core.AuraArray
	WeakenedSouls        core.AuraArray

	// The racial heals (racials.go): the human's Divine Grace and the
	// gnome's Contingency Plan, its ward, shield and heal over time.
	DivineGrace       *core.Spell
	ContingencyPlan   *core.Spell
	ContingencyShield *core.Spell
	ContingencyHot    *core.Spell
	ContingencyWards  core.AuraArray

	// lastHealSpellCode is the spell code of the last heal this priest
	// cast, which Litany of Light compares the next heal against.
	lastHealSpellCode int32
}

func (priest *Priest) GetCharacter() *core.Character {
	return &priest.Character
}

func (priest *Priest) AddRaidBuffs(raidBuffs *proto.RaidBuffs) {
	raidBuffs.ShadowProtection = true
	raidBuffs.DivineSpirit = true
	raidBuffs.PowerWordFortitude = max(
		raidBuffs.PowerWordFortitude,
		// FOREVER: Improved Power Word: Fortitude is not in the client's trees.
		// core.MakeTristateValue(true, priest.Talents.ImprovedPowerWordFortitude == 2),
		core.MakeTristateValue(true, false),
	)
}

func (priest *Priest) AddPartyBuffs(_ *proto.PartyBuffs) {
}

func (priest *Priest) Initialize() {
	priest.registerMindBlast()
	priest.registerMindFlay()
	priest.registerShadowWordDeathSpell()
	priest.registerShadowWordPainSpell()
	// Forever: Devouring Plague is a normal Shadow spell for every race, not
	// an Undead racial (SkillLineAbility carries every race for 2944-19280).
	priest.registerDevouringPlagueSpell()
	if priest.GetCharacter().Race == proto.Race_RaceNightElf {
		priest.registerStarshardsSpell()
	}
	priest.registerSmiteSpell()
	priest.registerHolyFire()
	priest.registerShootSpell()
	priest.registerShadowfiend()
	// Dark Sacrifice is the Undead racial: SkillLineAbility RaceMasks_0 16
	// on every rank (1277324-1277328).
	if priest.GetCharacter().Race == proto.Race_RaceUndead {
		priest.registerDarkSacrifice()
	}
}

func New(character *core.Character, talents string) *Priest {
	priest := &Priest{
		Character: *character,
		Talents:   &proto.PriestTalents{},
	}
	core.FillTalentsProto(priest.Talents.ProtoReflect(), talents, TalentTreeSizes)

	priest.EnableManaBar()

	priest.AddStatDependency(stats.Strength, stats.AttackPower, core.APPerStrength[character.Class])
	core.AddCritStatDependencies(&priest.Character, priest.Class)

	// Set mana regen to 12.5 + Spirit/4 each 2s tick
	priest.SpiritManaRegenPerSecond = func() float64 {
		return 6.25 + priest.GetStat(stats.Spirit)/8
	}

	return priest
}

// Agent is a generic way to access underlying priest on any of the agents.
type PriestAgent interface {
	GetPriest() *Priest
}
